@namespace sv_d026fb0e53b04fa3b4be3ae1a7231d5d.Components.Pages.Chat

<div class="emoji-picker">
    @foreach (var emoji in _emojis)
    {
        <button class="emoji-btn" @onclick="() => OnEmojiSelected.InvokeAsync(emoji)" title="@emoji">
            @emoji
        </button>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public EventCallback<string> OnEmojiSelected { get; set; }

    private static readonly string[] _emojis = ["👍", "❤️", "😂", "🎉", "😮", "🔥"];
}

.emoji-picker {
    display: flex;
    gap: 2px;
    background: var(--bs-body-bg, #fff);
    border: 1px solid var(--bs-border-color, #dee2e6);
    border-radius: 8px;
    padding: 4px 6px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
    position: absolute;
    bottom: 100%;
    right: 0;
    z-index: 10;
}

.emoji-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    padding: 4px 6px;
    border-radius: 4px;
    cursor: pointer;
    line-height: 1;
}

.emoji-btn:hover {
    background: var(--bs-tertiary-bg, #f0f0f0);
}

@namespace sv_d026fb0e53b04fa3b4be3ae1a7231d5d.Components.Pages.Chat

<div class="message-input">
    <textarea class="form-control" rows="2" placeholder="@Placeholder"
              @bind="_text" @bind:event="oninput"
              @onkeydown="HandleKeyDown"></textarea>
    <button class="btn btn-primary send-btn" disabled="@string.IsNullOrWhiteSpace(_text)"
            @onclick="Send">
        @ButtonText
    </button>
</div>

@code {
    [Parameter] public string Placeholder { get; set; } = "Type a message…";
    [Parameter] public string ButtonText { get; set; } = "Send";
    [Parameter, EditorRequired] public EventCallback<string> OnSubmit { get; set; }

    private string _text = string.Empty;

    private async Task Send()
    {
        if (string.IsNullOrWhiteSpace(_text)) return;
        var message = _text.Trim();
        _text = string.Empty;
        await OnSubmit.InvokeAsync(message);
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await Send();
        }
    }
}

.message-input {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid var(--bs-border-color, #dee2e6);
    background: var(--bs-body-bg, #fff);
    align-items: flex-end;
}

.message-input textarea {
    resize: none;
    flex: 1;
}

.send-btn {
    flex-shrink: 0;
    align-self: flex-end;
}

@namespace sv_d026fb0e53b04fa3b4be3ae1a7231d5d.Components.Pages.Chat

<button class="channel-item @(IsActive ? "active" : "")" @onclick="() => OnSelected.InvokeAsync(Channel.Id)">
    <div class="channel-header">
        <span class="channel-name"># @Channel.Name</span>
        @if (Channel.UnreadCount > 0)
        {
            <span class="badge bg-danger rounded-pill unread-badge">@Channel.UnreadCount</span>
        }
    </div>
    @if (!string.IsNullOrWhiteSpace(Channel.Description))
    {
        <div class="channel-desc text-muted">@TruncatedDescription</div>
    }
</button>

@code {
    [Parameter, EditorRequired] public Services.Channel Channel { get; set; } = default!;
    [Parameter] public bool IsActive { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnSelected { get; set; }

    private string TruncatedDescription =>
        Channel.Description.Length > 60
            ? Channel.Description[..57] + "…"
            : Channel.Description;
}

.channel-item {
    display: block;
    width: 100%;
    text-align: left;
    padding: 10px 14px;
    border: none;
    background: transparent;
    cursor: pointer;
    border-radius: 6px;
    margin-bottom: 2px;
    transition: background-color 0.15s;
}

.channel-item:hover {
    background: rgba(0, 0, 0, 0.06);
}

.channel-item.active {
    background: var(--bs-primary);
    color: #fff;
}

.channel-item.active .text-muted {
    color: rgba(255, 255, 255, 0.75) !important;
}

.channel-item.active .unread-badge {
    background-color: #fff !important;
    color: var(--bs-primary);
}

.channel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

.channel-desc {
    font-size: 0.78rem;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

