@namespace sv_d026fb0e53b04fa3b4be3ae1a7231d5d.Components.Pages.Chat

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h6 class="mb-0">Channels</h6>
    </div>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="channel.Id == ActiveChannelId"
                         OnSelected="OnChannelSelected" />
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<Services.Channel> Channels { get; set; } = [];
    [Parameter] public int? ActiveChannelId { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnChannelSelected { get; set; }
}

.channel-sidebar {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: var(--bs-tertiary-bg, #f8f9fa);
    border-right: 1px solid var(--bs-border-color, #dee2e6);
}

.sidebar-header {
    padding: 16px 14px 12px;
    border-bottom: 1px solid var(--bs-border-color, #dee2e6);
}

.channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 6px;
}

@namespace sv_d026fb0e53b04fa3b4be3ae1a7231d5d.Components.Pages.Chat

<div class="message-area">
    @if (Channel is not null)
    {
        <div class="area-header">
            <h5 class="mb-0"># @Channel.Name</h5>
            <span class="text-muted channel-description">@Channel.Description</span>
        </div>

        <div class="message-list" @onscroll="HandleScroll" @ref="_messageListRef">
            @if (IsLoadingMore)
            {
                <div class="text-center py-2">
                    <span class="spinner-border spinner-border-sm" role="status"></span>
                    <span class="text-muted ms-1">Loading older messages…</span>
                </div>
            }
            @foreach (var msg in Messages)
            {
                <MessageItem Message="msg"
                             ReplyCount="GetReplyCount(msg.Id)"
                             OnOpenThread="OnOpenThread"
                             OnReact="OnReact" />
            }
        </div>

        <MessageInput Placeholder="@($"Message #{Channel.Name}")"
                      ButtonText="Send"
                      OnSubmit="OnSendMessage" />
    }
    else
    {
        <div class="empty-state text-muted">
            <p>Select a channel to start chatting</p>
        </div>
    }
</div>

@code {
    [Parameter] public Services.Channel? Channel { get; set; }
    [Parameter, EditorRequired] public List<Services.Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter, EditorRequired] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter, EditorRequired] public EventCallback OnLoadOlderMessages { get; set; }

    private ElementReference _messageListRef;

    private int GetReplyCount(int messageId) =>
        ThreadReplyCounts.GetValueOrDefault(messageId);

    private async Task HandleScroll()
    {
        // Scroll-to-top detection is handled via JS interop in the page component.
        // Here we expose the element reference for the parent to use.
    }

    public ElementReference GetMessageListElement() => _messageListRef;
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    min-width: 0;
}

.area-header {
    padding: 14px 20px;
    border-bottom: 1px solid var(--bs-border-color, #dee2e6);
    flex-shrink: 0;
}

.channel-description {
    font-size: 0.85rem;
    display: block;
    margin-top: 2px;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.empty-state {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.1rem;
}

@namespace sv_d026fb0e53b04fa3b4be3ae1a7231d5d.Components.Pages.Chat

<div class="thread-panel">
    <div class="thread-header">
        <h6 class="mb-0">Thread</h6>
        <button class="btn-close" @onclick="OnClose" aria-label="Close thread"></button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-quote">
            <div class="quote-author">@RootMessage.Author</div>
            <div class="quote-content">@RootMessage.Content</div>
        </div>
    }

    <div class="thread-messages">
        @foreach (var reply in Replies)
        {
            <div class="thread-reply">
                <div class="reply-header">
                    <span class="reply-author">@reply.Author</span>
                    <span class="reply-time text-muted">@FormatRelativeTime(reply.SentAt)</span>
                </div>
                <div class="reply-content">@reply.Content</div>
                @if (reply.Reactions.Count > 0)
                {
                    <div class="reply-reactions">
                        @foreach (var reaction in reply.Reactions)
                        {
                            <span class="reaction-badge" title="@string.Join(", ", reaction.Users)">
                                @reaction.Emoji @reaction.Users.Count
                            </span>
                        }
                    </div>
                }
            </div>
        }
    </div>

    <MessageInput Placeholder="Reply in thread…"
                  ButtonText="Reply"
                  OnSubmit="OnReply" />
</div>

@code {
    [Parameter] public Services.Message? RootMessage { get; set; }
