toolArgs.file_text:
@namespace sv_d026fb0e53b04fa3b4be3ae1a7231d5d.Components.Pages.Chat

<div class="thread-panel">
    <div class="thread-header">
        <h6 class="mb-0">Thread</h6>
        <button class="btn-close" @onclick="OnClose" aria-label="Close thread"></button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-quote">
            <div class="quote-author">@RootMessage.Author</div>
            <div class="quote-content">@RootMessage.Content</div>
        </div>
    }

    <div class="thread-messages">
        @foreach (var reply in Replies)
        {
            <div class="thread-reply">
                <div class="reply-header">
                    <span class="reply-author">@reply.Author</span>
                    <span class="reply-time text-muted">@FormatRelativeTime(reply.SentAt)</span>
                </div>
                <div class="reply-content">@reply.Content</div>
                @if (reply.Reactions.Count > 0)
                {
                    <div class="reply-reactions">
                        @foreach (var reaction in reply.Reactions)
                        {
                            <span class="reaction-badge" title="@string.Join(", ", reaction.Users)">
                                @reaction.Emoji @reaction.Users.Count
                            </span>
                        }
                    </div>
                }
            </div>
        }
    </div>

    <MessageInput Placeholder="Reply in thread…"
                  ButtonText="Reply"
                  OnSubmit="OnReply" />
</div>

@code {
    [Parameter] public Services.Message? RootMessage { get; set; }
    [Parameter, EditorRequired] public List<Services.Message> Replies { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback<string> OnReply { get; set; }
    [Parameter, EditorRequired] public EventCallback OnClose { get; set; }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

