toolArgs.file_text:
.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    border-left: 1px solid var(--bs-border-color, #dee2e6);
    background: var(--bs-body-bg, #fff);
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 14px 16px;
    border-bottom: 1px solid var(--bs-border-color, #dee2e6);
    flex-shrink: 0;
}

.thread-root-quote {
    padding: 12px 16px;
    margin: 10px 12px;
    background: var(--bs-tertiary-bg, #f8f9fa);
    border-left: 3px solid var(--bs-primary);
    border-radius: 4px;
    flex-shrink: 0;
}

.quote-author {
    font-weight: 700;
    font-size: 0.88rem;
    margin-bottom: 2px;
}

.quote-content {
    font-size: 0.85rem;
    color: var(--bs-secondary-color, #6c757d);
    white-space: pre-wrap;
    word-break: break-word;
}

.thread-messages {
    flex: 1;
    overflow-y: auto;
    padding: 4px 0;
}

.thread-reply {
    padding: 8px 16px;
}

.reply-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.reply-author {
    font-weight: 700;
    font-size: 0.9rem;
}

.reply-time {
    font-size: 0.73rem;
}

.reply-content {
    font-size: 0.9rem;
    line-height: 1.4;
    white-space: pre-wrap;
    word-break: break-word;
}

.reply-reactions {
    display: flex;
    gap: 4px;
    margin-top: 4px;
    flex-wrap: wrap;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 3px;
    padding: 2px 8px;
    font-size: 0.78rem;
    background: var(--bs-tertiary-bg, #f0f0f0);
    border: 1px solid var(--bs-border-color, #dee2e6);
    border-radius: 12px;
}

