@page "/chat"
@namespace sv_d026fb0e53b04fa3b4be3ae1a7231d5d.Components.Pages.Chat
@using sv_d026fb0e53b04fa3b4be3ae1a7231d5d.Services
@rendermode InteractiveServer
@inject IChatService ChatService
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="_channels"
                        ActiveChannelId="_selectedChannel?.Id"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(_threadOpen ? "" : "expanded")">
        <MessageArea @ref="_messageArea"
                     Channel="_selectedChannel"
                     Messages="_messages"
                     ThreadReplyCounts="_threadReplyCounts"
                     IsLoadingMore="_loadingMore"
                     OnSendMessage="SendMessage"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnLoadOlderMessages="LoadOlderMessages" />
    </div>

    @if (_threadOpen && _threadRootMessage is not null)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnReply="SendThreadReply"
                         OnClose="CloseThread" />
        </div>
    }
</div>

@code {
    private List<Channel> _channels = [];
    private Channel? _selectedChannel;
    private List<Message> _messages = [];
    private Dictionary<int, int> _threadReplyCounts = [];
    private bool _loadingMore;

    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    private MessageArea? _messageArea;
    private IJSObjectReference? _jsModule;
    private DotNetObjectReference<ChatPage>? _dotNetRef;

    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _jsModule = await JS.InvokeAsync<IJSObjectReference>("import",
                "./_content/sv-d026fb0e53b04fa3b4be3ae1a7231d5d/Components/Pages/Chat/ChatPage.razor.js");
        }

        if (_messageArea is not null && _jsModule is not null)
        {
            var el = _messageArea.GetMessageListElement();
            await _jsModule.InvokeVoidAsync("observeScrollTop", el, _dotNetRef);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        var channel = _channels.FirstOrDefault(c => c.Id == channelId);
        if (channel is null) return;

        _selectedChannel = channel;
        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channelId);
        await ComputeThreadReplyCounts();

        // Update unread badge locally
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = channel with { UnreadCount = 0 };
        }
    }

    private async Task SendMessage(string content)
    {
        if (_selectedChannel is null) return;
        var msg = await ChatService.SendMessageAsync(_selectedChannel.Id, content, null);
        _messages.Add(msg);
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to reflect updated reactions
        if (_selectedChannel is not null)
        {
            _messages = await ChatService.GetMessagesAsync(_selectedChannel.Id, 0, _messages.Count);
        }
    }

    private async Task OpenThread(int rootMessageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (_threadRootMessage is null) return;

        _threadReplies = await ChatService.GetThreadAsync(rootMessageId);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null || _selectedChannel is null) return;
        var reply = await ChatService.SendMessageAsync(_selectedChannel.Id, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);
        await ComputeThreadReplyCounts();
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (_loadingMore || _selectedChannel is null) return;
        await LoadOlderMessages();
    }

    private async Task LoadOlderMessages()
    {
        if (_loadingMore || _selectedChannel is null) return;

        _loadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_selectedChannel.Id, _messages.Count, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
        }

        _loadingMore = false;
    }

    private async Task ComputeThreadReplyCounts()
    {
        // Build reply counts from messages that are replies (have ReplyToId set)
        _threadReplyCounts = _messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());

        await Task.CompletedTask;
    }

    async ValueTask IAsyncDisposable.DisposeAsync()
    {
        _dotNetRef?.Dispose();
        if (_jsModule is not null)
        {
            try { await _jsModule.DisposeAsync(); }
            catch (JSDisconnectedException) { }
        }
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 300px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    min-width: 0;
    transition: flex 0.2s ease;
}

.chat-main.expanded {
    flex: 1;
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    max-width: 400px;
    flex-shrink: 0;
}

let observedElement = null;
let observer = null;

export function observeScrollTop(element, dotNetRef) {
    if (!element || observedElement === element) return;

    if (observer) {
        observer.disconnect();
    }

    observedElement = element;

    // Use a scroll event listener to detect when scrolled near the top
    element.addEventListener('scroll', () => {
        if (element.scrollTop < 40) {
            dotNetRef.invokeMethodAsync('OnScrolledToTop');
        }
    }, { passive: true });
}

