let observedElement = null;
let observer = null;

export function observeScrollTop(element, dotNetRef) {
    if (!element || observedElement === element) return;

    if (observer) {
        observer.disconnect();
    }

    observedElement = element;

    // Use a scroll event listener to detect when scrolled near the top
    element.addEventListener('scroll', () => {
        if (element.scrollTop < 40) {
            dotNetRef.invokeMethodAsync('OnScrolledToTop');
        }
    }, { passive: true });
}

